#include "ordinary_escher.hpp"
#include <iostream>
using namespace study;
int main(){try{size_t cases=0,placements=0,patterns=0,providers=0,rejected=0,warmRetained=0;for(size_t trial=0;trial<6;++trial){Input input;input.width=30;input.height=20;input.pitch=.25;input.randomSeed=uint32_t(19+trial);PartInput part;part.polygon={{0,0},{6,0},{6,2},{2,2},{2,6},{0,6}};part.poses={{0,false},{180,false}};part.quantity=trial%2?12:20;input.parts.push_back(part);
  if(trial%3==1){PartInput second;second.polygon={{0,0},{3,0},{3,2},{0,2}};second.poses={{0,false},{180,false}};second.quantity=8;input.parts.push_back(second);}
  Budget budget(20.);recovered::OffsetFactoryInput factory;factory.dynamicEvaluation=trial%4>0;auto program=escherProgram(input,10.,factory);program.trial13bc=int32_t(trial%4);OrdinaryState state;
  if(trial>=3){OrdinaryControl initial;initial.placementLimit=0;for(const auto &p:input.parts)initial.values.push_back(area(p.polygon));ordinaryRun(input,budget,state,&initial);ordinaryCommit(state,{0,0,0,0,0});}
  OrdinaryEscherTrace trace;const auto before=state.output.placements.size();const auto added=ordinaryEscherContinue(input,program,budget,state,&trace);require(added==int32_t(state.output.placements.size()-before),PN2S_INTERNAL,"Escher reports a count different from committed ordinary instances");require(valid_layout(input,state.output),PN2S_INTERNAL,"Escher ordinary batch, fallback or warm continuation failed the real layout validator");std::set<std::pair<size_t,size_t>> identities;for(const auto &placement:state.output.placements)require(identities.emplace(placement.group,placement.ordinal).second,PN2S_INTERNAL,"Escher placed an instance twice");if(before){require(!state.output.placements.empty()&&state.output.placements.front().group==0&&state.output.placements.front().ordinal==0&&state.output.placements.front().x==0&&state.output.placements.front().y==0,PN2S_INTERNAL,"Escher changed or removed a warm obstacle");++warmRetained;}
  require(trace.missingProviders.empty(),PN2S_INTERNAL,"Escher runtime reached an unrecovered provider branch");require(trace.providers>0&&trace.patternRequests>0&&trace.rawPatterns>0,PN2S_INTERNAL,"Escher runtime did not use its actual pattern provider");require(!state.output.placements.empty(),PN2S_INTERNAL,"Escher runtime produced no placements");
  for(size_t group=0;group<input.parts.size();++group){size_t actual=0;for(const auto &placement:state.output.placements)actual+=placement.group==group;const auto &catalog=*state.catalog;const auto &record=catalog.records.at(catalog.groups[group].front());require(record.nestedCount==int32_t(actual)&&actual<=size_t(input.parts[group].quantity),PN2S_INTERNAL,"Escher live ordinary catalog quantity disagrees with actual placements");}
  std::cout<<"{\"scene\":"<<trial<<",\"placed\":"<<state.output.placements.size()<<",\"patternPlaced\":"<<trace.committed<<",\"providerCalls\":"<<trace.patternRequests<<",\"warm\":"<<before<<",\"rejected\":"<<trace.rejectedPatterns<<"}\n";++cases;placements+=state.output.placements.size();patterns+=trace.committed;providers+=trace.providers;rejected+=trace.rejectedPatterns;
 }
 std::cout<<"{\"pass\":true,\"ordinaryCases\":"<<cases<<",\"placements\":"<<placements<<",\"patternCommitted\":"<<patterns<<",\"providers\":"<<providers<<",\"rejectedPatterns\":"<<rejected<<",\"warmRetained\":"<<warmRetained<<"}\n";return 0;
}catch(const std::exception &error){std::cerr<<error.what()<<'\n';return 1;}}
